actions.script:
const kinds = ['workItem', 'time', 'project']
kind = kinds.includes(kind) ? kind : 'workItem'
hasRecord = !!(recordEntity && recordId)
recordLabel = hasRecord ? (recordTitle || recordId) : null
myPartyId = ec.user.userAccount?.partyId || null
myName = ec.user.userAccount?.userFullName || ec.user.username
// the project: of the list, of the work effort of the screen context (a project, or the project of a work item), else the first
projectOptions = ec.service.sync().name('ironstone.projects.WorkItemServices.get#ProjectOptions').parameters({memberOnly: true}).call()?.projectList || []
let projectId = rootWorkEffortId || null
if (!projectId && hasRecord && recordEntity === 'mantle.work.effort.WorkEffort') {
    const record = ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', recordId).one()
    projectId = record?.workEffortTypeEnumId === 'WetProject' ? record.workEffortId : (record?.rootWorkEffortId || null)
}
defaultProjectId = projectId && projectOptions.some((option) => option.key === projectId) ? projectId : (projectOptions[0]?.key || '')
linkRecord = hasRecord && recordEntity !== 'mantle.work.effort.WorkEffort'
// the types the project offers (its WstWorkItemTypes, else the organization's; Settings, Work item types)
typeOptions = Array.from(ec.service.sync().name('ironstone.projects.ProjectServices.get#WorkItemTypes').parameters({rootWorkEffortId: defaultProjectId || null}).call()?.offeredList || [])
defaultTypeId = typeOptions.some((type) => type.enumId === 'WepTask') ? 'WepTask' : (typeOptions[0]?.enumId || 'WepTask')
isProjectsManager = ec.user.isInGroup('BOSS_PROJECT_MANAGER') || ec.user.isInGroup('ADMIN')
// time: the work item of the screen context (a task or a project), else the first of mine and recent
timeItemOptions = Array.from(ec.service.sync().name('ironstone.projects.TimeServices.search#TimeItems').call()?.optionList || [])
defaultTimeItem = ''
if (hasRecord && recordEntity === 'mantle.work.effort.WorkEffort') {
    const record = ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', recordId).one()
    // only an item the user may see is named (HiddenItems.js mayName)
    if (record && ['WetTask', 'WetProject'].includes(record.workEffortTypeEnumId)
            && ec.resource.script('component://mr-boss/service/ironstone/projects/HiddenItems.js').mayName(record.workEffortId)) {
        defaultTimeItem = record.workEffortId
        if (!timeItemOptions.some((option) => option.value === defaultTimeItem))
            timeItemOptions.unshift({value: defaultTimeItem, label: defaultTimeItem + ' ' + (record.workEffortName || '')})
    }
}
if (!defaultTimeItem && timeItemOptions.length) defaultTimeItem = timeItemOptions[0].value
todayText = ec.l10n.format(ec.user.nowTimestamp, 'yyyy-MM-dd')
// the work types the user's organization offers (Settings, Time: mantle.work.TimesheetServices.get#WorkTypes)
workTypeOptions = Array.from(ec.service.sync().name('mantle.work.TimesheetServices.get#WorkTypes').call()?.offeredList || [])
        .map((type) => ({key: type.enumId, text: type.label}))
